namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Location { get; set; } = "";
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and rhetoric." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and civilizations." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 50 papers and holds 3 patents in fault-tolerant architectures.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Miller", Title = "Associate Professor of Mathematics", Bio = "Dr. Miller's research focuses on algebraic topology and its applications to data analysis. He received the Distinguished Teaching Award in 2023.", Email = "j.miller@university.edu" },
            new() { Id = 3, Name = "Prof. Emily Rodriguez", Title = "Professor of English", Bio = "Prof. Rodriguez is a published novelist and literary critic specializing in contemporary American fiction and creative writing pedagogy.", Email = "e.rodriguez@university.edu" },
            new() { Id = 4, Name = "Dr. Michael Park", Title = "Professor of Physics", Bio = "Dr. Park leads the Quantum Materials Lab and has been recognized for bridging theoretical and experimental physics research.", Email = "m.park@university.edu" },
            new() { Id = 5, Name = "Dr. Lisa Thompson", Title = "Associate Professor of History", Bio = "Dr. Thompson is an expert in medieval European history with a focus on social structures and cultural exchange along trade routes.", Email = "l.thompson@university.edu" },
            new() { Id = 6, Name = "Dr. Robert Kim", Title = "Assistant Professor of Computer Science", Bio = "Dr. Kim researches machine learning and natural language processing, with a focus on making AI systems more interpretable.", Email = "r.kim@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "Advanced study of data organization and algorithm design. Topics include trees, graphs, dynamic programming, and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Science Hall 305", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[5], IsFeatured = true },
            new() { Id = 3, Code = "CS 450", Title = "Machine Learning", Description = "Theory and practice of machine learning. Covers supervised and unsupervised learning, neural networks, and model evaluation techniques.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Tech Center 110", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[5], IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Calculus II", Description = "Continuation of single-variable calculus. Topics include integration techniques, sequences, series, and introduction to multivariable calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 102", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = false },
            new() { Id = 5, Code = "MATH 310", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, eigenvalues, and applications to data science and engineering.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Math Building 204", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = true },
            new() { Id = 6, Code = "ENG 102", Title = "Academic Writing", Description = "Development of critical thinking and writing skills for academic contexts. Emphasis on argument construction, evidence use, and revision.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Humanities 315", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 7, Code = "ENG 350", Title = "Creative Writing Workshop", Description = "Workshop-based course in fiction and poetry. Students produce original work and engage in peer critique.", Credits = 3, Schedule = "Wed 3:00–5:50 PM", Location = "Humanities 210", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = true },
            new() { Id = 8, Code = "PHYS 201", Title = "Classical Mechanics", Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations. Applications to oscillations, central forces, and rigid body motion.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Physics Lab 101", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = false },
            new() { Id = 9, Code = "PHYS 410", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, and applications to atomic physics.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", Location = "Physics Lab 203", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = true },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the late medieval period. Covers political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM", Location = "Liberal Arts 405", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0;
    }
}

